CREATE TABLE IF NOT EXISTS pairing_challenges(code_hash TEXT PRIMARY KEY,child_uid TEXT NOT NULL,device_id TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at INTEGER);\nCREATE INDEX IF NOT EXISTS pairing_expiry_idx ON pairing_challenges(expires_at);\nCREATE TABLE IF NOT EXISTS device_links(device_id TEXT PRIMARY KEY,child_uid TEXT NOT NULL,parent_uid TEXT NOT NULL,linked_at INTEGER NOT NULL,revoked_at INTEGER);\nCREATE INDEX IF NOT EXISTS device_links_parent_idx ON device_links(parent_uid);